import {
  Component,
  ChangeDetectionStrategy,
  signal,
  computed,
} from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { ScheconPageLayoutComponent } from '../../../../shared/components/schecon-page-layout/schecon-page-layout.component';
import { CalendarWeekViewMiniComponent } from '../../../../shared/components/calendar-week-view-mini/calendar-week-view-mini.component';
import { NotificationService } from '../../../../shared/services/notification.service';

interface CandidateSlot {
  date: string;
  dayOfWeek: string;
  timeRange: string;
  checked: boolean;
}

@Component({
  selector: 'app-group-create-page',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ReactiveFormsModule,
    MatIconModule,
    ScheconPageLayoutComponent,
    CalendarWeekViewMiniComponent,
  ],
  templateUrl: './group-create-page.component.html',
  styleUrl: './group-create-page.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class GroupCreatePageComponent {
  step1Form: FormGroup;
  step2Form: FormGroup;

  includeWeekends = signal(false);
  includeAllDay = signal(true);
  showOptions = signal(false);

  candidateSlots = signal<CandidateSlot[]>(this.generateMockSlots());
  checkedCount = computed(() => this.candidateSlots().filter(s => s.checked).length);

  participants = signal<string[]>(['山田太郎', '佐藤花子']);

  mtgTools = [
    'オンラインMTGでは行わない',
    'Zoom',
    'Google Meet',
    'Microsoft Teams',
  ];

  organizers = ['ishizawamoph@gmail.com', '山田太郎', '佐藤花子', '鈴木一郎'];
  availableParticipants = ['田中健', '高橋美咲', '伊藤大輔', '渡辺紗希', '中村翔太'];

  constructor(
    private fb: FormBuilder,
    private location: Location,
    private notification: NotificationService,
  ) {
    this.step1Form = this.fb.group({
      eventName: ['', Validators.required],
      isPrivate: [false],
      mtgTool: ['オンラインMTGでは行わない'],
      location: [''],
    });

    this.step2Form = this.fb.group({
      organizer: ['ishizawamoph@gmail.com'],
      hideParticipantNames: [false],
      period: ['2weeks'],
      timeSlot: ['meeting'],
      duration: ['60'],
      travelTime: ['none'],
    });
  }

  toggleSlot(index: number): void {
    this.candidateSlots.update(slots =>
      slots.map((s, i) => i === index ? { ...s, checked: !s.checked } : s)
    );
  }

  removeParticipant(name: string): void {
    this.participants.update(p => p.filter(n => n !== name));
    this.notification.info('参加者を削除しました');
  }

  addParticipant(name: string): void {
    if (name && !this.participants().includes(name)) {
      this.participants.update(p => [...p, name]);
      this.notification.info('参加者を追加しました');
    }
  }

  onCreate(): void {
    if (this.step1Form.invalid) {
      this.notification.error('予定の名前を入力してください');
      return;
    }
    this.notification.success('予定調整を作成しました');
  }

  addNextWeek(): void {
    this.notification.info('翌週の候補を追加しました');
  }

  addWithExisting(): void {
    this.notification.info('既存の予定がある日も候補に追加しました');
  }

  selectPeriod(): void {
    this.notification.info('期間を選択しました');
  }

  refreshCalendar(): void {
    this.notification.info('カレンダーから日程を再取得しました');
  }

  goBack(): void {
    this.location.back();
  }

  private generateMockSlots(): CandidateSlot[] {
    const slots: CandidateSlot[] = [];
    const data = [
      { date: '04/07', dow: '火', time: '09:30 - 11:30' },
      { date: '04/08', dow: '水', time: '14:00 - 16:00' },
      { date: '04/09', dow: '木', time: '09:30 - 10:30' },
      { date: '04/09', dow: '木', time: '14:00 - 18:30' },
      { date: '04/10', dow: '金', time: '16:00 - 19:00' },
      { date: '04/13', dow: '月', time: '12:30 - 13:30' },
      { date: '04/13', dow: '月', time: '16:00 - 18:00' },
      { date: '04/14', dow: '火', time: '09:30 - 13:30' },
      { date: '04/15', dow: '水', time: '12:30 - 13:30' },
      { date: '04/15', dow: '水', time: '16:30 - 19:00' },
      { date: '04/16', dow: '木', time: '09:30 - 10:30' },
      { date: '04/16', dow: '木', time: '12:30 - 18:30' },
      { date: '04/17', dow: '金', time: '09:30 - 10:30' },
      { date: '04/17', dow: '金', time: '12:30 - 13:30' },
      { date: '04/17', dow: '金', time: '17:30 - 18:30' },
    ];
    data.forEach(d => {
      slots.push({ date: d.date, dayOfWeek: d.dow, timeRange: d.time, checked: true });
    });
    return slots;
  }
}
